final class SN_Future24_Review_Hardening_E {
    private const RECONCILE_BATCH=100;
    public static function register():void{add_action('rest_api_init',[self::class,'routes'],1990);add_action('sn_cleanup_hourly',[self::class,'cleanup_breakouts'],40);}
    public static function routes():void{
        register_rest_route('sabri-network/v2','/calls/(?P<id>\d+)/breakouts',['methods'=>'POST','callback'=>[self::class,'create_breakouts'],'permission_callback'=>[SN_REST::class,'access']],true);
        register_rest_route('sabri-network/v2','/calls/(?P<id>\d+)/breakouts/move',['methods'=>'POST','callback'=>[self::class,'move_breakout'],'permission_callback'=>[SN_REST::class,'access']]);
        register_rest_route('sabri-network/v2','/calls/(?P<id>\d+)/breakouts/close',['methods'=>'POST','callback'=>[self::class,'close_breakouts'],'permission_callback'=>[SN_REST::class,'access']]);
    }
    public static function create_breakouts(WP_REST_Request $r):WP_REST_Response|WP_Error{
        global $wpdb;$call=absint($r['id']);$actor=get_current_user_id();if(!self::call_manager($call,$actor))return self::error('forbidden','Call host permission is required.',403);
        $rooms=is_array($r->get_param('rooms'))?$r->get_param('rooms'):[];if(!$rooms||count($rooms)>20)return self::error('sn_breakouts_invalid','Provide 1 to 20 breakout rooms.',400);$seen=[];$clean=[];$index=0;
        foreach($rooms as $room){$name=mb_substr(sanitize_text_field((string)($room['name']??'')),0,100);$users=array_values(array_unique(array_filter(array_map('absint',(array)($room['user_ids']??[])))));if($name===''||!$users)return self::error('sn_breakout_room_invalid','Each breakout room needs a name and participants.',400);foreach($users as $u){if(isset($seen[$u]))return self::error('sn_breakout_duplicate_participant','A participant may be assigned to only one breakout room.',409);if(!self::call_member($call,$u))return self::error('sn_breakout_participant_invalid','Every breakout participant must be an active call member.',409);$seen[$u]=true;}$clean[]=['room_id'=>'br-'.(++$index),'name'=>$name,'user_ids'=>$users,'state'=>'active'];}
        if(!(bool)apply_filters('sn_network_sfu_available',false,$actor,$call))return self::error('sn_breakout_provider_unavailable','Breakout rooms require an approved SFU adapter.',503);
        $lock=self::lifecycle_lock($call);if(is_wp_error($lock))return $lock;
        try{
            if(!self::call_manager($call,$actor))return self::error('forbidden','Call host authority changed before breakout creation.',403);foreach(array_keys($seen) as $uid)if(!self::call_member($call,(int)$uid))return self::error('sn_breakout_participant_invalid','A participant left the parent call before breakout creation.',409);
            $expires=gmdate('Y-m-d H:i:s',time()+max(15,min(480,absint($r->get_param('ttl_minutes'))?:120))*MINUTE_IN_SECONDS);$operation=wp_generate_uuid4();$data=['parent_call_id'=>$call,'rooms'=>$clean,'assignments'=>[],'provider_room_refs'=>[],'created_by'=>$actor,'expires_at'=>$expires,'operation_id'=>$operation,'provider_phase'=>'provisioning'];
            $row=self::lifecycle_row($call,true);if($row&&in_array((string)$row->state,['active','moving','closing','provisioning','expiry_pending','reconcile_required'],true))return self::error('sn_breakout_conflict','Another breakout lifecycle is already active for this call.',409);
            $record=self::save_lifecycle($row,$call,$data,'provisioning',$expires);if(is_wp_error($record))return $record;$id=(int)$record['id'];$version=(int)$record['version'];
            $provider=apply_filters('sn_network_breakout_create_result',null,$call,$clean,$actor,['operation_id'=>$operation,'idempotency_key'=>'file17-breakout-create:'.$id.':'.$version]);
            if($provider===null||$provider===false||is_wp_error($provider)){self::transition_state($id,$version,'provisioning','provider_failed');return is_wp_error($provider)?$provider:self::error('sn_breakout_provider_unavailable','Breakout rooms require an approved SFU adapter.',503);}
            $refs=[];foreach((array)($provider['room_refs']??[]) as $k=>$ref){$v=mb_substr(sanitize_text_field((string)$ref),0,191);if($v!=='')$refs[(string)$k]=$v;}$data['provider_room_refs']=$refs;$data['provider_result_hash']=hash('sha256',(string)wp_json_encode($provider));$data['provider_phase']='active';
            $final=self::finalize_payload($id,$version,$data,'provisioning','active',$expires);if(is_wp_error($final)){$rolled=apply_filters('sn_network_breakout_close_result',null,$call,$actor,$data+['compensation_for'=>'create_finalize_failure']);if($rolled!==null&&$rolled!==false&&!is_wp_error($rolled))self::force_reconcile_terminal($id,'provider_rolled_back');else self::force_reconcile_required($id,$data+['reconcile_action'=>'close']);return self::error('sn_breakout_reconcile_required','Provider creation succeeded but local finalization failed; reconciliation was queued.',503);}
            SN_DB::audit('future_breakouts_created','call',$call,'success',['breakout_record_id'=>$id,'room_count'=>count($clean),'expires_at'=>$expires,'operation_id'=>$operation],$actor);return rest_ensure_response(['call_id'=>$call,'breakout_record_id'=>$id,'rooms'=>$clean,'expires_at'=>$expires]);
        }finally{self::lifecycle_unlock($lock);}
    }
    public static function move_breakout(WP_REST_Request $r):WP_REST_Response|WP_Error{
        $call=absint($r['id']);$actor=get_current_user_id();if(!self::call_manager($call,$actor))return self::error('forbidden','Call host permission is required.',403);$target=absint($r->get_param('user_id'));$room=sanitize_key((string)$r->get_param('room_id'));if(!$target||!self::call_member($call,$target))return self::error('sn_breakout_participant_invalid','Participant is no longer in the parent call.',409);
        $lock=self::lifecycle_lock($call);if(is_wp_error($lock))return $lock;
        try{
            if(!self::call_manager($call,$actor)||!self::call_member($call,$target))return self::error('sn_breakout_participant_invalid','Host authority or participant membership changed before move.',409);$row=self::lifecycle_row($call,true);if(!$row||(string)$row->state!=='active')return self::error('sn_breakouts_unavailable','No stable active breakout set exists.',409);$data=self::decode($row);if(is_wp_error($data))return $data;$valid=$room==='parent';if(!$valid)foreach((array)($data['rooms']??[]) as $entry)if((string)($entry['room_id']??'')===$room&&($entry['state']??'')==='active'){$valid=true;break;}if(!$valid)return self::error('sn_breakout_room_invalid','Select an active breakout or parent room.',409);
            $previous=(string)($data['assignments'][(string)$target]??'parent');$data['pending_move']=['user_id'=>$target,'from'=>$previous,'to'=>$room,'requested_by'=>$actor,'operation_id'=>wp_generate_uuid4()];$pending=self::finalize_payload((int)$row->id,(int)$row->version,$data,'active','moving',(string)$row->expires_at);if(is_wp_error($pending))return $pending;$version=(int)$row->version+1;
            $provider=apply_filters('sn_network_breakout_move_result',null,$call,$target,$room,$actor,$data);if($provider===null||$provider===false||is_wp_error($provider)){unset($data['pending_move']);$data['provider_phase']='active';self::finalize_payload((int)$row->id,$version,$data,'moving','active',(string)$row->expires_at);return is_wp_error($provider)?$provider:self::error('sn_breakout_provider_unavailable','The conference provider could not move this participant.',503);}
            $data['assignments'][(string)$target]=$room;unset($data['pending_move']);$data['provider_phase']='active';$saved=self::finalize_payload((int)$row->id,$version,$data,'moving','active',(string)$row->expires_at);if(is_wp_error($saved)){$rollback=apply_filters('sn_network_breakout_move_rollback_result',null,$call,$target,$previous,$actor,['failed_target'=>$room,'record_id'=>(int)$row->id]);if($rollback!==null&&$rollback!==false&&!is_wp_error($rollback))self::force_active_after_move_rollback((int)$row->id,$target,$previous);else self::force_reconcile_required((int)$row->id,['reconcile_action'=>'move_rollback','user_id'=>$target,'room_id'=>$previous,'failed_target'=>$room]);return self::error('sn_breakout_reconcile_required','Provider move succeeded but local finalization failed; reconciliation was queued.',503);}
