        }finally{self::lifecycle_unlock($lock);}
    }
    public static function close_breakouts(WP_REST_Request $r):WP_REST_Response|WP_Error{
        $call=absint($r['id']);$actor=get_current_user_id();if(!self::call_manager($call,$actor))return self::error('forbidden','Call host permission is required.',403);$lock=self::lifecycle_lock($call);if(is_wp_error($lock))return $lock;
        try{if(!self::call_manager($call,$actor))return self::error('forbidden','Call host authority changed before close.',403);$row=self::lifecycle_row($call,true);if(!$row||in_array((string)$row->state,['closed','expired','provider_failed','provider_rolled_back'],true))return rest_ensure_response(['call_id'=>$call,'state'=>'closed']);if((string)$row->state!=='active')return self::error('sn_breakout_conflict','Breakout lifecycle is busy; retry close.',409);$data=self::decode($row);if(is_wp_error($data))return $data;$pending=self::transition_state((int)$row->id,(int)$row->version,'active','closing');if(is_wp_error($pending))return $pending;$provider=apply_filters('sn_network_breakout_close_result',null,$call,$actor,$data+['idempotency_key'=>'file17-breakout-close:'.(int)$row->id]);if($provider===null||$provider===false||is_wp_error($provider)){self::transition_state((int)$row->id,(int)$row->version+1,'closing','active');return is_wp_error($provider)?$provider:self::error('sn_breakout_provider_unavailable','The conference provider could not close the breakouts safely.',503);}$closed=self::transition_state((int)$row->id,(int)$row->version+1,'closing','closed');if(is_wp_error($closed)){self::force_reconcile_required((int)$row->id,$data+['reconcile_action'=>'close']);return self::error('sn_breakout_reconcile_required','Provider closed the breakouts but local finalization requires reconciliation.',503);}SN_DB::audit('future_breakouts_closed','call',$call,'success',['record_id'=>(int)$row->id],$actor);return rest_ensure_response(['call_id'=>$call,'state'=>'closed']);}finally{self::lifecycle_unlock($lock);}
    }
    public static function cleanup_breakouts():void{
        global $wpdb;$now=current_time('mysql',true);$batch=self::RECONCILE_BATCH;
        // Claim due active rows before generic Future-24 cleanup can expire them blindly.
        $wpdb->query($wpdb->prepare("UPDATE ".$wpdb->prefix."sn_future_records SET state='expiry_pending',updated_at=%s,version=version+1 WHERE feature_id='F17-FUT-19' AND state='active' AND expires_at IS NOT NULL AND expires_at<=%s LIMIT $batch",$now,$now));
        $rows=$wpdb->get_results("SELECT id,scope_id,state FROM ".$wpdb->prefix."sn_future_records WHERE feature_id='F17-FUT-19' AND state IN ('expiry_pending','closing','reconcile_required','provisioning','moving') ORDER BY id ASC LIMIT ".self::RECONCILE_BATCH);
        foreach(is_array($rows)?$rows:[] as $stub){$call=(int)$stub->scope_id;$lock=self::lifecycle_lock($call,0);if(is_wp_error($lock))continue;try{$row=self::row_by_id((int)$stub->id,true);if(!$row)continue;$data=self::decode($row);if(is_wp_error($data))continue;$state=(string)$row->state;if($state==='moving'){$pending=(array)($data['pending_move']??[]);$target=absint($pending['user_id']??0);$previous=sanitize_key((string)($pending['from']??'parent'));$rollback=apply_filters('sn_network_breakout_move_rollback_result',null,$call,$target,$previous,0,['record_id'=>(int)$row->id,'recovery'=>true]);if($rollback!==null&&$rollback!==false&&!is_wp_error($rollback))self::force_active_after_move_rollback((int)$row->id,$target,$previous);continue;}$provider=apply_filters('sn_network_breakout_close_result',null,$call,0,$data+['recovery'=>true,'state'=>$state]);if($provider===null||$provider===false||is_wp_error($provider)){self::force_reconcile_required((int)$row->id,$data+['reconcile_action'=>'close']);continue;}$terminal=$state==='expiry_pending'?'expired':($state==='closing'?'closed':'provider_rolled_back');self::force_reconcile_terminal((int)$row->id,$terminal);SN_DB::audit('future_breakouts_'.$terminal,'call',$call,'success',['record_id'=>(int)$row->id,'recovered'=>true],0);}finally{self::lifecycle_unlock($lock);}}
    }
    private static function lifecycle_row(int $call,bool $lock=false):?object{global $wpdb;$sql="SELECT * FROM ".$wpdb->prefix."sn_future_records WHERE feature_id='F17-FUT-19' AND scope_type='call' AND scope_id=%d ORDER BY id DESC LIMIT 1".($lock?' FOR UPDATE':'');$row=$wpdb->get_row($wpdb->prepare($sql,$call));return is_object($row)?$row:null;}
    private static function row_by_id(int $id,bool $lock=false):?object{global $wpdb;$sql="SELECT * FROM ".$wpdb->prefix."sn_future_records WHERE id=%d AND feature_id='F17-FUT-19' LIMIT 1".($lock?' FOR UPDATE':'');$row=$wpdb->get_row($wpdb->prepare($sql,$id));return is_object($row)?$row:null;}
    private static function save_lifecycle(?object $row,int $call,array $data,string $state,string $expires):array|WP_Error{global $wpdb;$dummy=$row?:((object)['feature_id'=>'F17-FUT-19','owner_id'=>0,'scope_type'=>'call','scope_id'=>$call,'version'=>0]);$cipher=self::encode($dummy,$data);if(is_wp_error($cipher))return $cipher;$now=current_time('mysql',true);if($row){$ok=$wpdb->update($wpdb->prefix.'sn_future_records',['payload_cipher'=>$cipher,'state'=>$state,'expires_at'=>$expires,'updated_at'=>$now,'version'=>(int)$row->version+1],['id'=>(int)$row->id,'version'=>(int)$row->version]);return $ok===1?['id'=>(int)$row->id,'version'=>(int)$row->version+1]:self::error('sn_breakout_conflict','Breakout state changed concurrently.',409);}$ok=$wpdb->insert($wpdb->prefix.'sn_future_records',['feature_id'=>'F17-FUT-19','owner_id'=>0,'scope_type'=>'call','scope_id'=>$call,'state'=>$state,'payload_cipher'=>$cipher,'client_key'=>hash('sha256','breakouts:'.$call),'expires_at'=>$expires,'created_at'=>$now,'updated_at'=>$now,'version'=>1]);return $ok===1?['id'=>(int)$wpdb->insert_id,'version'=>1]:self::error('database_error','Breakout lifecycle could not be stored safely.',500);}
    private static function finalize_payload(int $id,int $version,array $data,string $from,string $to,string $expires):bool|WP_Error{global $wpdb;$row=self::row_by_id($id,false);if(!$row)return self::error('sn_breakout_conflict','Breakout state changed concurrently.',409);$cipher=self::encode($row,$data);if(is_wp_error($cipher))return $cipher;$ok=$wpdb->update($wpdb->prefix.'sn_future_records',['payload_cipher'=>$cipher,'state'=>$to,'expires_at'=>$expires,'updated_at'=>current_time('mysql',true),'version'=>$version+1],['id'=>$id,'state'=>$from,'version'=>$version]);return $ok===1?true:self::error('sn_breakout_conflict','Breakout state changed concurrently.',409);}
    private static function transition_state(int $id,int $version,string $from,string $to):bool|WP_Error{global $wpdb;$ok=$wpdb->update($wpdb->prefix.'sn_future_records',['state'=>$to,'updated_at'=>current_time('mysql',true),'version'=>$version+1],['id'=>$id,'state'=>$from,'version'=>$version]);return $ok===1?true:self::error('sn_breakout_conflict','Breakout state changed concurrently.',409);}
    private static function force_reconcile_required(int $id,array $data):void{global $wpdb;$row=self::row_by_id($id,false);if(!$row)return;$cipher=self::encode($row,$data);$wpdb->update($wpdb->prefix.'sn_future_records',['payload_cipher'=>is_wp_error($cipher)?$row->payload_cipher:$cipher,'state'=>'reconcile_required','updated_at'=>current_time('mysql',true),'version'=>(int)$row->version+1],['id'=>$id,'version'=>(int)$row->version]);SN_DB::audit('future_breakout_reconcile_required','future_record',$id,'failure',['scope_id'=>(int)$row->scope_id],0);}
