    private static function force_active_after_move_rollback(int $id,int $target,string $previous):void{global $wpdb;$row=self::row_by_id($id,false);if(!$row)return;$data=self::decode($row);if(is_wp_error($data))return;$data['assignments'][(string)$target]=$previous;unset($data['pending_move']);$data['provider_phase']='active';$cipher=self::encode($row,$data);if(is_wp_error($cipher))return;$wpdb->update($wpdb->prefix.'sn_future_records',['payload_cipher'=>$cipher,'state'=>'active','updated_at'=>current_time('mysql',true),'version'=>(int)$row->version+1],['id'=>$id,'version'=>(int)$row->version]);}
    private static function call_member(int $call,int $u):bool{global $wpdb;return(bool)$wpdb->get_var($wpdb->prepare("SELECT id FROM ".SN_DB::table('call_members')." WHERE call_id=%d AND user_id=%d AND status IN ('invited','joined') LIMIT 1",$call,$u));}
    private static function call_manager(int $call,int $u):bool{global $wpdb;$c=(int)$wpdb->get_var($wpdb->prepare('SELECT conversation_id FROM '.SN_DB::table('calls').' WHERE id=%d',$call));if(!$c)return false;$host=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".$wpdb->prefix."sn_future_records WHERE feature_id='F17-FUT-20' AND scope_type='call' AND scope_id=%d AND state='active' ORDER BY id DESC LIMIT 1",$call));if($host){$d=self::decode($host);if(!is_wp_error($d)&&(int)($d['host_id']??0)===$u)return true;}return in_array(SN_DB::member_role($c,$u),['owner','moderator'],true)||user_can($u,'manage_options');}
    private static function lifecycle_lock(int $call,int $wait=5):string|WP_Error{global $wpdb;$name='sn:f17:breakout:'.$call;$got=(int)$wpdb->get_var($wpdb->prepare('SELECT GET_LOCK(%s,%d)',$name,$wait));return $got===1?$name:self::error('sn_breakout_busy','Breakout lifecycle is busy; retry.',409);}
